class Solution {
public:
    double minAreaFreeRect(vector<vector<int>>& points) {
        map<tuple<int, int, int>, vector<pair<int, int>>> groups;
        int n = points.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int cx = points[i][0] + points[j][0];
                int cy = points[i][1] + points[j][1];
                int d2 = (points[i][0] - points[j][0]) * (points[i][0] - points[j][0]) +
                         (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]);
                groups[{cx, cy, d2}].push_back({i, j});
            }
        }
        double min_area = 1e18;
        for (const auto& [_, pairs] : groups) {
            int m = pairs.size();
            for (int i = 0; i < m; ++i) {
                int p1 = pairs[i].first, p2 = pairs[i].second;
                for (int j = i + 1; j < m; ++j) {
                    int p3 = pairs[j].first;
                    double side1 = hypot(points[p1][0] - points[p3][0], points[p1][1] - points[p3][1]);
                    double side2 = hypot(points[p2][0] - points[p3][0], points[p2][1] - points[p3][1]);
                    min_area = min(min_area, side1 * side2);
                }
            }
        }
        return min_area == 1e18 ? 0.0 : min_area;
    }
};

class Solution {
    public double minAreaFreeRect(int[][] points) {
        Map<String, List<int[]>> groups = new HashMap<>();
        int n = points.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int cx = points[i][0] + points[j][0];
                int cy = points[i][1] + points[j][1];
                int d2 = (points[i][0] - points[j][0]) * (points[i][0] - points[j][0]) +
                         (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]);
                String key = cx + "," + cy + "," + d2;
                groups.computeIfAbsent(key, k -> new ArrayList<>()).add(new int[]{i, j});
            }
        }
        double minArea = Double.MAX_VALUE;
        for (List<int[]> pairs : groups.values()) {
            int m = pairs.size();
            for (int i = 0; i < m; i++) {
                int p1 = pairs.get(i)[0], p2 = pairs.get(i)[1];
                for (int j = i + 1; j < m; j++) {
                    int p3 = pairs.get(j)[0];
                    double side1 = Math.hypot(points[p1][0] - points[p3][0], points[p1][1] - points[p3][1]);
                    double side2 = Math.hypot(points[p2][0] - points[p3][0], points[p2][1] - points[p3][1]);
                    minArea = Math.min(minArea, side1 * side2);
                }
            }
        }
        return minArea == Double.MAX_VALUE ? 0.0 : minArea;
    }
}

var minAreaFreeRect = function(points) {
    const groups = new Map();
    const n = points.length;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const cx = points[i][0] + points[j][0];
            const cy = points[i][1] + points[j][1];
            const d2 = (points[i][0] - points[j][0]) ** 2 + (points[i][1] - points[j][1]) ** 2;
            const key = cx + ',' + cy + ',' + d2;
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push([i, j]);
        }
    }
    let minArea = Infinity;
    for (const pairs of groups.values()) {
        const m = pairs.length;
        for (let i = 0; i < m; i++) {
            const [p1, p2] = pairs[i];
            for (let j = i + 1; j < m; j++) {
                const p3 = pairs[j][0];
                const side1 = Math.hypot(points[p1][0] - points[p3][0], points[p1][1] - points[p3][1]);
                const side2 = Math.hypot(points[p2][0] - points[p3][0], points[p2][1] - points[p3][1]);
                minArea = Math.min(minArea, side1 * side2);
            }
        }
    }
    return minArea === Infinity ? 0.0 : minArea;
};
